const words=[{word:'Concise',level:'Beginner',meaning:'Giving a lot of information clearly in a few words.',sentence:'Write a concise README so new contributors can get started quickly.',synonyms:'brief, compact'}, {word:'Resilient',level:'Intermediate',meaning:'Able to recover quickly after difficulty or failure.',sentence:'A resilient service recovers gracefully after a temporary network issue.',synonyms:'robust, adaptable'}, {word:'Deterministic',level:'Academic',meaning:'Producing the same result from the same inputs under the same conditions.',sentence:'A deterministic test is easier to reproduce and debug.',synonyms:'predictable, consistent'}, {word:'Ephemeral',level:'Advanced',meaning:'Lasting for only a short time.',sentence:'The application stores the preview token in ephemeral session state.',synonyms:'transient, fleeting'}, {word:'Pragmatic',level:'Intermediate',meaning:'Focused on practical results rather than theory alone.',sentence:'A pragmatic first release prioritizes dependable core features.',synonyms:'practical, realistic'}];
